insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-2a', 'world-2', 'signal-path', '2A - Signal Path', 'Trace one suspicious connection from a raw packet dump to a real understanding of how it got there.', 1);
insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-2a-1', 'campaign-2a', 'foundations', 'Foundations', 'Layers, hops and topology, learned as tools for reading the capture.', 1),
  ('operation-2a-2', 'campaign-2a', 'investigation', 'Investigation', 'Apply those tools to the flagged connection itself.', 2);
insert into public.missions (
insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-w2-01', 1, 'zayn', 'The program you flagged just made a call -- one connection, one IP address, and about forty thousand packets of data I need you to actually understand, not just stare at.'),
  ('mission-w2-01', 2, 'zayn', 'Everyone starts here confused. A network isn''t magic. It''s just messages, handed off machine to machine, each one adding its own little envelope. Let''s follow one.'),
  ('mission-w2-02', 1, 'zayn', 'Every one of those forty thousand packets is stacked like an envelope inside an envelope. Before we chase the destination, you need to know which layer does what.'),
  ('mission-w2-03', 1, 'zayn', 'One message doesn''t teleport to its destination. It jumps -- laptop to switch to router to the wider internet. Trace the actual path.'),
  ('mission-w2-04', 1, 'zayn', 'Some of this capture looks like packet loss. Most of it isn''t. Tell the difference before you write a report that''s wrong.'),
  ('mission-w2-05', 1, 'zayn', 'Last piece before the boss briefing: know the room. Every device here plays a specific role in whether that connection could even happen.'),
  ('mission-w2-06', 1, 'zayn', 'Full picture now. Reconstruct the whole path, and tell me what''s actually strange about it -- not just where it goes.'),
  ('mission-w2-06', 2, 'zayn', 'Every hop checks out. Ordinary route, ordinary devices. It''s the timing that isn''t ordinary.'),
  ('mission-w2-06', 3, 'byte', 'I ran the interval against itself. It''s not close to regular -- it is regular. Machine-regular.'),
  ('mission-w2-06', 4, 'zayn', 'The destination itself rotates every few minutes, but the rhythm underneath it doesn''t change. That''s not how a person browses. That''s a schedule.'),
  ('mission-w2-06', 5, 'zayn', 'And the trail dies right at our own switch -- whatever''s really happening lives inside the local network, not out on the internet. We need to understand switching before we go any further.');
insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-w2-01-o1', 'mission-w2-01', 1, 'Acknowledge the briefing', 'Confirm you''re ready to start tracing the connection.'),
  ('mission-w2-02-o1', 'mission-w2-02', 1, 'Match the layer', 'Assign each piece of the conversation to the OSI layer that actually handles it.'),
  ('mission-w2-03-o1', 'mission-w2-03', 1, 'Order the hops', 'Order the path from the workstation to the remote destination.'),
  ('mission-w2-04-o1', 'mission-w2-04', 1, 'Diagnose the anomalies', 'Separate what''s genuinely tied to the flagged destination from normal local network noise.'),
  ('mission-w2-05-o1', 'mission-w2-05', 1, 'Place each device', 'Assign each device to its functional role in the topology.'),
  ('mission-w2-06-o1', 'mission-w2-06', 1, 'Reconstruct the path', 'Order the full authorized path from the workstation to the flagged destination.'),
  ('mission-w2-06-o2', 'mission-w2-06', 2, 'Identify the pattern', 'Prove the connection''s timing is automated rather than a person browsing.'),
  ('mission-w2-06-o3', 'mission-w2-06', 3, 'Brief command', 'Summarize the path and the pattern for Luna''s incident review.');
insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-w2-01-o1-c1', 'mission-w2-01-o1', 1, 'story_dialogue', 'Confirm you''re ready to continue.', '{"lines":[{"characterId":"zayn","text":"One connection, traced properly, teaches you more than a wall of packet data ever will. Ready to start?"}]}'::jsonb, '{"acknowledged":true}'::jsonb),
  ('mission-w2-02-o1-c1', 'mission-w2-02-o1', 1, 'drag_and_drop', 'Match each piece of the conversation to the layer that handles it.', '{"items":[{"id":"ethernet","text":"Ethernet frame"},{"id":"ip","text":"IP packet"},{"id":"tcp","text":"TCP segment"},{"id":"http","text":"HTTP request"}],"targets":[{"id":"l2","label":"Layer 2 -- Data Link (local delivery)"},{"id":"l3","label":"Layer 3 -- Network (addressing/routing)"},{"id":"l4","label":"Layer 4 -- Transport (reliable delivery)"},{"id":"l7","label":"Layer 7 -- Application (what the user actually wants)"}]}'::jsonb, '{"correctMapping":{"ethernet":"l2","ip":"l3","tcp":"l4","http":"l7"}}'::jsonb),
  ('mission-w2-03-o1-c1', 'mission-w2-03-o1', 1, 'interactive_diagram', 'Order these from the workstation to the remote destination.', '{"hotspots":[{"id":"laptop","label":"Recruit workstation","explanation":"Where the connection actually originates."},{"id":"switch","label":"Local switch","explanation":"Forwards frames within the same local network segment."},{"id":"router","label":"Gateway router","explanation":"The first device that can leave the local network entirely."},{"id":"isp","label":"ISP hand-off","explanation":"Where traffic leaves Guardian-controlled infrastructure onto the wider internet."},{"id":"dest","label":"Remote host","explanation":"The suspicious destination address itself."}],"task":"Order these from the workstation to the remote destination."}'::jsonb, '{"correctOrderIds":["laptop","switch","router","isp","dest"]}'::jsonb),
  ('mission-w2-04-o1-c1', 'mission-w2-04-o1', 1, 'investigation', 'Which entries indicate something worth investigating about the flagged destination itself, rather than normal local network noise?', '{"evidence":[{"id":"e1","label":"3 retransmits, one TCP stream, ~200ms apart","detail":"Occurred once, during a known Wi-Fi handoff between access points"},{"id":"e2","label":"Steady 1% packet loss on a single stream to the flagged destination","detail":"Consistent across the entire ten-minute capture, unrelated to any local network event"},{"id":"e3","label":"One ICMP time-exceeded reply from an intermediate router","detail":"A single, expected reply during normal traceroute-style probing"},{"id":"e4","label":"Round-trip time to the flagged destination cycles between 40ms and 340ms","detail":"Repeats every few minutes, does not correlate with any local network activity"}],"question":"Which entries indicate something worth investigating about the flagged destination itself, rather than normal local network noise?"}'::jsonb, '{"requiredEvidenceIds":["e2","e4"]}'::jsonb),
  ('mission-w2-05-o1-c1', 'mission-w2-05-o1', 1, 'drag_and_drop', 'Assign each device to its functional role.', '{"items":[{"id":"workstation","text":"Recruit workstation"},{"id":"switch","text":"Access switch"},{"id":"firewall","text":"Perimeter firewall"},{"id":"router","text":"Edge router"},{"id":"server","text":"Internal file server"}],"targets":[{"id":"endpoint","label":"Endpoint -- generates/receives traffic"},{"id":"l2-forward","label":"Layer 2 -- forwards within the local segment"},{"id":"boundary","label":"Boundary -- enforces what traffic is allowed through"},{"id":"l3-forward","label":"Layer 3 -- forwards between networks"}]}'::jsonb, '{"correctMapping":{"workstation":"endpoint","switch":"l2-forward","firewall":"boundary","router":"l3-forward","server":"endpoint"}}'::jsonb),
  ('mission-w2-06-o1-c1', 'mission-w2-06-o1', 1, 'interactive_diagram', 'Order the full path from the workstation to the flagged destination.', '{"hotspots":[{"id":"workstation","label":"Recruit workstation","explanation":"Connection origin."},{"id":"switch","label":"Access switch","explanation":"Local forwarding only."},{"id":"firewall","label":"Perimeter firewall","explanation":"Enforces the boundary rule set."},{"id":"router","label":"Edge router","explanation":"Forwards beyond the local network."},{"id":"dest","label":"Flagged remote host","explanation":"The rotating destination address."}],"task":"Order the full path from the workstation to the flagged destination."}'::jsonb, '{"correctOrderIds":["workstation","switch","firewall","router","dest"]}'::jsonb),
  ('mission-w2-06-o2-c1', 'mission-w2-06-o2', 1, 'investigation', 'Which evidence proves this is automated, scheduled behavior rather than a person''s normal browsing?', '{"evidence":[{"id":"ev1","label":"Destination IP changes","detail":"A new destination address roughly every 4-6 minutes"},{"id":"ev2","label":"Interval between connection attempts","detail":"300 seconds, measured across dozens of samples, deviation under 1%"},{"id":"ev3","label":"Payload size","detail":"Varies per request, consistent with normal application traffic"},{"id":"ev4","label":"User activity correlation","detail":"Connections continue on the exact same interval whether or not anyone is using the workstation"}],"question":"Which evidence proves this is automated, scheduled behavior rather than a person''s normal browsing?"}'::jsonb, '{"requiredEvidenceIds":["ev2","ev4"]}'::jsonb),
  ('mission-w2-06-o3-c1', 'mission-w2-06-o3', 1, 'boss_encounter', 'Summarize the path and the pattern for Luna''s incident review.', '{"stages":[{"objectiveRef":"mission-w2-06-o1","label":"The reconstructed path"},{"objectiveRef":"mission-w2-06-o2","label":"The timing pattern"}],"task":"Summarize the path and the pattern for Luna''s incident review."}'::jsonb, '{"requiredObjectiveIds":["mission-w2-06-o1","mission-w2-06-o2"],"allCorrect":true}'::jsonb);
insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-w2-01-o1-c1', 'orientation', 'There''s nothing to solve here -- just confirm you''re ready to continue.', 0, 1),
  ('mission-w2-02-o1-c1', 'orientation', 'Each layer answers one specific question about the message -- start with ''what does this layer actually decide?''', 10, 1),
  ('mission-w2-02-o1-c1', 'concept', 'Addressing between two directly connected devices is a different question than addressing across the whole internet.', 20, 2),
  ('mission-w2-02-o1-c1', 'solution', 'Ethernet handles local delivery (L2), IP handles internet-wide addressing (L3), TCP handles reliable delivery (L4), and HTTP is the actual application request (L7).', 30, 3),
  ('mission-w2-03-o1-c1', 'orientation', 'Start from the one device you know for certain is first: the workstation itself.', 10, 1),
  ('mission-w2-03-o1-c1', 'concept', 'A switch only knows about its own local segment -- it can''t be the one that leaves the network.', 20, 2),
  ('mission-w2-03-o1-c1', 'solution', 'laptop -> switch -> router -> ISP hand-off -> remote host is the path a locally-originated connection actually takes leaving the network.', 30, 3),
  ('mission-w2-04-o1-c1', 'orientation', 'Some of this is completely ordinary network behavior that happens on any connection. Two entries aren''t.', 10, 1),
  ('mission-w2-04-o1-c1', 'concept', 'Ask which anomalies are tied to something local and explainable, versus something specific to the one suspicious stream.', 20, 2),
  ('mission-w2-04-o1-c1', 'tool_direction', 'Check whether each anomaly correlates with a known local event or repeats independent of anything happening on this end.', 30, 3),
  ('mission-w2-04-o1-c1', 'solution', 'The steady 1% loss and the cyclical RTT swing are both isolated to the flagged stream with no local explanation -- the Wi-Fi handoff retransmits and the single ICMP reply are both normal, explainable network behavior.', 40, 4),
  ('mission-w2-05-o1-c1', 'orientation', 'Two of these five devices generate or receive traffic; the other three exist purely to move or control it.', 10, 1),
  ('mission-w2-05-o1-c1', 'concept', 'A firewall''s whole purpose is deciding what''s allowed through, not moving traffic between networks.', 20, 2),
  ('mission-w2-05-o1-c1', 'solution', 'Workstation and server are endpoints; the switch forwards locally; the router forwards between networks; the firewall enforces the boundary between them.', 30, 3),
  ('mission-w2-06-o1-c1', 'orientation', 'This is the same kind of ordering as the earlier hop-tracing mission, just with the topology roles folded in.', 15, 1),
  ('mission-w2-06-o1-c1', 'concept', 'The boundary-enforcing device has to sit between local forwarding and anything that reaches beyond the network.', 25, 2),
  ('mission-w2-06-o1-c1', 'tool_direction', 'Place the firewall relative to the switch and the router, then the destination last.', 35, 3),
  ('mission-w2-06-o1-c1', 'solution', 'workstation -> switch -> firewall -> router -> flagged destination is the full authorized path leaving the network.', 45, 4),
  ('mission-w2-06-o2-c1', 'orientation', 'A person''s browsing habits are irregular by nature -- look for what isn''t.', 15, 1),
  ('mission-w2-06-o2-c1', 'concept', 'A near-perfectly fixed interval and behavior that doesn''t depend on a human being present are both machine signatures.', 25, 2),
  ('mission-w2-06-o2-c1', 'tool_direction', 'Check which two entries would still be true even if no one ever touched the workstation.', 35, 3),
  ('mission-w2-06-o2-c1', 'solution', 'The near-perfectly fixed 300-second interval and its continuation with no user present both point to automated, scheduled behavior -- the changing destination and normal payload size are both consistent with either explanation on their own.', 45, 4),
  ('mission-w2-06-o3-c1', 'orientation', 'You''ve already gathered everything you need -- this is about combining the two findings into one brief.', 20, 1),
  ('mission-w2-06-o3-c1', 'concept', 'Command needs both halves: where the connection actually goes, and why its timing alone proves it isn''t human.', 30, 2),
  ('mission-w2-06-o3-c1', 'tool_direction', 'State the path first, then the timing evidence, then what the combination implies.', 40, 3),
  ('mission-w2-06-o3-c1', 'near_solution', 'The path is ordinary and authorized; the timing is what isn''t -- that combination is the whole finding.', 50, 4),
  ('mission-w2-06-o3-c1', 'solution', 'The connection follows the ordinary authorized path out of the network, but a machine-regular 300-second interval underneath a rotating destination proves this is scheduled, automated behavior -- not a person browsing.', 60, 5);
